import { array } from "numpy-ts";
import { Animation, classDefaultsOf } from "./animation.js";
import { VMobject } from "../mobject/types/vectorized_mobject.js";
import { linear } from "../utils/rate_functions.js";
import { pointRows, isNDArray, nestedRows, addPoints, scalePoint } from "../utils/arrays.js";
export class Homotopy extends Animation {
    homotopy;
    apply_function_kwargs;
    constructor(homotopy, mobject, options = {}) {
        super(mobject, { run_time: 3, ...options });
        this.homotopy = homotopy;
        this.apply_function_kwargs = options.apply_function_kwargs ?? {};
    }
    function_at_time_t(t) {
        const mapping_function = (point) => {
            let values;
            if (isNDArray(point))
                values = nestedRows(point)[0]?.map(Number) ?? [];
            else if (Array.isArray(point))
                values = point.map(Number);
            else if ("re" in point)
                values = [point.re, point.im, 0];
            else
                values = [point.real, point.imag, 0];
            if (values.length !== 3) {
                const error = new Error(`not enough values to unpack (expected 3, got ${values.length})`);
                error.name = "ValueError";
                throw error;
            }
            const [x, y, z] = values;
            const result = this.homotopy(x, y, z, t);
            if (isNDArray(result))
                return result.copy();
            if (typeof result === "number")
                return array([result, 0, z]);
            if (Array.isArray(result))
                return array(result);
            return array("re" in result ? [result.re, result.im, z] : [result.real, result.imag, z]);
        };
        return mapping_function;
    }
    interpolate_submobject(submobject, startingSubmobject, alpha) {
        // Copy, not share: `apply_function` below may mutate the array in place,
        // which would otherwise corrupt the animation's starting snapshot.
        const sp = startingSubmobject.points;
        submobject.points = isNDArray(sp) ? sp.copy() : sp;
        submobject.apply_function(this.function_at_time_t(alpha), this.apply_function_kwargs.about_point, this.apply_function_kwargs.about_edge);
        return this;
    }
}
export class SmoothedVectorizedHomotopy extends Homotopy {
    interpolate_submobject(submobject, startingSubmobject, alpha) {
        // Mirrors Python `assert isinstance(submobject, VMobject)`. (In manim
        // 0.21.0 the assert itself raises NameError at runtime because VMobject
        // is only imported under TYPE_CHECKING; the port implements the evident
        // intent: assert the type, apply the homotopy, then make_smooth().)
        if (!(submobject instanceof VMobject)) {
            const error = new Error(`assert isinstance(submobject, VMobject): got ${submobject?.constructor?.name ?? typeof submobject}`);
            error.name = "AssertionError";
            throw error;
        }
        super.interpolate_submobject(submobject, startingSubmobject, alpha);
        const vmobject = submobject;
        vmobject.make_smooth?.();
        return this;
    }
}
export class ComplexHomotopy extends Homotopy {
    constructor(complex_homotopy, mobject, options = {}) {
        const homotopy = (x, y, _z, t) => {
            const result = complex_homotopy({ re: x, im: y }, t);
            if (typeof result === "number")
                return [result, 0, _z];
            if (isNDArray(result))
                return pointRows(result, 3)[0] ?? [_z, _z, _z];
            if (Array.isArray(result))
                return result;
            return "re" in result ? [result.re, result.im, _z] : [result.real, result.imag, _z];
        };
        super(homotopy, mobject, options);
    }
}
export class MoveAlongPath extends Animation {
    path;
    constructor(mobject, path, options = {}) {
        super(mobject, { suspend_mobject_updating: false, ...options });
        this.path = path;
    }
    interpolate_mobject(alpha) {
        this.mobject.move_to(this.path.point_from_proportion(this.rate_func(alpha)));
    }
}
export class PhaseFlow extends Animation {
    virtual_time;
    function;
    last_alpha;
    constructor(function_, mobject, options = {}) {
        const clsDefaults = classDefaultsOf(new.target);
        const { virtual_time = clsDefaults.virtual_time ?? 1, suspend_mobject_updating = clsDefaults.suspend_mobject_updating ?? false, rate_func = clsDefaults.rate_func ?? linear, ...rest } = options;
        super(mobject, { ...rest, suspend_mobject_updating, rate_func });
        this.virtual_time = virtual_time;
        this.function = function_;
    }
    interpolate_mobject(alpha) {
        if (this.last_alpha !== undefined) {
            const dt = this.virtual_time * (this.rate_func(alpha) - this.rate_func(this.last_alpha));
            const fn = this.function;
            this.mobject.apply_function((point) => addPoints(point, scalePoint(fn([...point]), dt, this.mobject.dim), this.mobject.dim));
        }
        this.last_alpha = alpha;
    }
}
